      description: 'Keep the document outline correct while controlling the visual scale',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['typography', 'heading', 'title'],
  intent: {
    whenToUse: [
      'Titling a page or section as part of the document outline',
